STRUCT = {0: 'position classes of argmax(x0..x8) chosen by 1-D clustering + local search; P=8 class fitted (very negative)', 1: '3 gain classes for argmax(x0..x8); memory set {0,4,7} chosen from 3 candidates', 2: 'window x0..x4 and the x2 term chosen by search over windows/feature triples', 3: 'position classes of argmax(x0..x8) chosen by clustering + local search; P=8 class fitted (very negative)', 4: '3 gain classes for argmax(x0..x8); memory position 8 chosen', 5: '3 gain classes for argmax and 2 classes for arg-second of x0..x8, by clustering + local search', 6: 'position classes of argmax(x0..x8) chosen by clustering + local search; P=8 class fitted (very negative)', 7: '3 gain classes for argmax(x0..x8); memory set {3,6}', 8: '3 gain classes for argmax(x0..x8); memory set {2,5}', 9: '3 gain classes for argmax(x0..x8); memory position 1', 10: '', 11: '3 gain classes for argmax(x0..x8); memory position 7', 12: '3 gain classes for argmax(x0..x8); memory set {2,5,8}', 13: '3 gain classes for argmax(x0..x8); memory set {0,1,3}', 14: '3 gain classes for argmax(x0..x8); memory position 8', 15: ''}

def _feat(x):
    x = np.asarray(x, dtype=float)
    o = np.argsort(-x[:, :9], 1)
    s = -np.sort(-x[:, :9], 1)
    return o[:, 0], o[:, 1], s[:, 0], s[:, 1], x[:, 9]

def f(i, x):
    x = np.asarray(x, dtype=float)
    P, Q, M, S, x9 = _feat(x)
    sp = SPEC[i]; th = sp["th"]; form = sp["form"]
    if form == "new":
        z = th[0] * (x9 - M)
    elif form == "top2x9":
        z = th[0] * x9 - th[1] * S + th[2] * M
    elif form == "win2b":
        w = -np.sort(-x[:, :5], 1)
        z = th[0] * w[:, 1] + th[1] * np.maximum(x[:, 2], 0) + th[2] * S
    else:
        g = np.array(th[:3])[np.array(sp["cg"])[P]] * M
        if form == "G3S_U":
            z = g + th[3] * S + th[4] * x9
        elif form == "G3H2":
            z = g + np.array(th[3:5])[np.array(sp["ch"])[Q]] * S
        elif form == "G3S_mem":
            z = g + th[3] * S + th[4] * np.maximum(x[:, sp["A"]], 0).sum(1)
    return np.maximum(0.0, z)
